+      countryCode: current.countryCode,
+      data: { ...current.data, step1Review: true },
+    });
+  }
+
+  /** Returns true once after `flagStep1Review`, then clears the flag. */
+  consumeStep1Review(): boolean {
+    const current = this.read();
