import { Injectable } from '@angular/core';

export const QUOTE_SESSION_KEY = 'quote-session';

export type Step1Values = Record<string, string | boolean>;

export interface QuoteSession {
  countryCode: string;
  data: Record<string, unknown>;
}

/** Single persistence helper for the quote wizard (sessionStorage). Never stores tokens. */
@Injectable({ providedIn: 'root' })
export class QuoteSessionStore {
  read(): QuoteSession | null {
    try {
      const raw = sessionStorage.getItem(QUOTE_SESSION_KEY);
      if (!raw) return null;
      const parsed: unknown = JSON.parse(raw);
      if (typeof parsed !== 'object' || parsed === null) return null;
      const { countryCode, data } = parsed as Partial<QuoteSession>;
      if (typeof countryCode !== 'string' || !countryCode) return null;
      const safeData =
        typeof data === 'object' && data !== null && !Array.isArray(data) ? data : {};
      return { countryCode, data: safeData };
    } catch {
      return null;
    }
  }

  lastCountryCode(): string | null {
    return this.read()?.countryCode ?? null;
  }

  /** True only when step 1 holds a non-empty string (trimmed) or a checked box. */
  hasData(): boolean {
    return Object.values(this.readStep1()).some(
      (value) => value === true || (typeof value === 'string' && value.trim() !== ''),
    );
  }

  readStep1(): Step1Values {
    const raw = this.read()?.data['step1'];
    if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) return {};
    const values: Step1Values = {};
    for (const [key, value] of Object.entries(raw)) {
      if (typeof value === 'string' || typeof value === 'boolean') values[key] = value;
    }
    return values;
  }

  /** Saves step 1 values; any earlier completion no longer applies. */
  saveStep1(values: Step1Values): void {
    const current = this.read();
    if (!current) return;
    const rest = { ...current.data };
    delete rest['step1Completed'];
    this.write({ countryCode: current.countryCode, data: { ...rest, step1: { ...values } } });
  }

  markStep1Completed(): void {
    const current = this.read();
    if (!current) return;
    this.write({
      countryCode: current.countryCode,
      data: { ...current.data, step1Completed: true },
    });
  }

  /** Step 1 no longer counts as complete (its saved values failed the re-check). */
  clearStep1Completed(): void {
    const current = this.read();
    if (!current) return;
    const rest = { ...current.data };
    delete rest['step1Completed'];
    this.write({ countryCode: current.countryCode, data: rest });
  }

  /** R-02: the guard asks step 1 to show its errors once (consumed by `consumeStep1Review`). */
  flagStep1Review(): void {
    const current = this.read();
    if (!current) return;
    this.write({
      countryCode: current.countryCode,
      data: { ...current.data, step1Review: true },
    });
  }

  /** Returns true once after `flagStep1Review`, then clears the flag. */
  consumeStep1Review(): boolean {
    const current = this.read();
    if (current?.data['step1Review'] !== true) return false;
    const rest = { ...current.data };
    delete rest['step1Review'];
    this.write({ countryCode: current.countryCode, data: rest });
    return true;
  }

  isStep1Completed(): boolean {
    return this.read()?.data['step1Completed'] === true;
  }

  /** Remembers the chosen plan (documentId) for this tab. */
  savePlan(planId: string): void {
    const current = this.read();
    if (!current) return;
    this.write({ countryCode: current.countryCode, data: { ...current.data, planId } });
  }

  readPlanId(): string | null {
    const id = this.read()?.data['planId'];
    return typeof id === 'string' && id !== '' ? id : null;
  }

  clearPlan(): void {
    const current = this.read();
    if (!current) return;
    const rest = { ...current.data };
    delete rest['planId'];
    this.write({ countryCode: current.countryCode, data: rest });
  }

  /** Same country keeps data; a different country resets it. */
  start(countryCode: string): void {
    const current = this.read();
    const data = current?.countryCode === countryCode ? current.data : {};
    this.write({ countryCode, data });
  }

  /** Keeps the country, empties the form data. */
  discardData(): void {
    const current = this.read();
    if (current) this.write({ countryCode: current.countryCode, data: {} });
  }

  clear(): void {
    try {
      sessionStorage.removeItem(QUOTE_SESSION_KEY);
    } catch {
      /* storage unavailable */
    }
  }

  private write(session: QuoteSession): void {
    try {
      sessionStorage.setItem(QUOTE_SESSION_KEY, JSON.stringify(session));
    } catch {
      /* storage unavailable: degrade to no persistence */
    }
  }
}
import { inject } from '@angular/core';
import { FormControl, FormGroup } from '@angular/forms';
import { ActivatedRouteSnapshot, CanActivateFn, Router, UrlTree } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { QuoteSessionStore } from '../../core/session/quote-session.store';
import { FormFieldService } from '../quote-form/data/form-field.service';
import { buildValidators } from '../quote-form/validation/build-validators';
import { restoredValue } from '../quote-form/validation/restored-value';
import { FieldValue } from '../quote-form/validation/validation.model';
import { WizardCountry } from './wizard-country.service';

/**
 * FR-011 / R8: later steps open only when step 1 was completed AND its saved values are still
 * valid against the current CMS fields. Otherwise the completion is cleared and the person goes
 * back to step 1, where the errors show. Fields that fail to load also go back to step 1.
 */
export const step1CompleteGuard: CanActivateFn = async (
  route: ActivatedRouteSnapshot,
): Promise<boolean | UrlTree> => {
  const session = inject(QuoteSessionStore);
  const router = inject(Router);
  const country = route.parent?.paramMap.get('country') ?? route.paramMap.get('country') ?? '';
  const toStep1 = router.createUrlTree(['/', country, 'quote']);
  if (!session.isStep1Completed()) return toStep1;

  const active = inject(WizardCountry).country();
  try {
    const sections = await firstValueFrom(inject(FormFieldService).load(country));
    const stored = session.readStep1();
    const ctx = { legalAge: active?.legalAge ?? 18, today: new Date() };
    const controls: Record<string, FormControl<FieldValue>> = {};
    for (const field of [...sections.policyholder, ...sections.vehicle]) {
      controls[field.key] = new FormControl<FieldValue>(restoredValue(field, stored[field.key]), {
        nonNullable: true,
        validators: buildValidators(field.rules, ctx, field.key),
      });
    }
    if (new FormGroup(controls).valid) return true;
    // R-02: step 1 shows the errors and focuses the first invalid field once.
    session.flagStep1Review();
  } catch {
    /* fields failed to load: step 1 shows its own error and retry */
  }
  session.clearStep1Completed();
  return toStep1;
};
        titleDelay,
        fields: fields.map((field) => ({ field, delay: index++ })),
      });
    }
    return views;
  });
  protected readonly isEmpty = computed(
    () => !this.loading() && !this.failed() && this.sections().length === 0,
  );
  protected readonly buttonDelay = computed(
    () => 1 + this.sections().reduce((n, s) => n + 1 + s.fields.length, 0),
  );

  constructor() {
    afterNextRender(() => this.host.nativeElement.querySelector<HTMLElement>('h1')?.focus());
    this.load();
  }

  protected load(): void {
    const country = this.wizardCountry.country();
    if (!country) return;
    this.loadSub?.unsubscribe();
    this.loading.set(true);
    this.failed.set(false);
    this.loadSub = this.fieldService.load(country.code).subscribe({
      next: (sections) => {
        this.form.set(this.buildForm(sections, country.legalAge));
        this.loaded.set(sections);
        this.loading.set(false);
        // R-02: the guard sent us back because the saved values are no longer valid.
        if (this.session.consumeStep1Review()) afterNextRender(() => this.showErrors(), { injector: this.injector });
      },
      error: () => {
        this.failed.set(true);
        this.loading.set(false);
      },
    });
  }

  private buildForm(sections: FormSections, legalAge: number): Step1Group {
    const stored = this.session.readStep1();
    const today = new Date();
    const controls: Record<string, FormControl<FieldValue>> = {};
    for (const field of [...sections.policyholder, ...sections.vehicle]) {
      const initial = restoredValue(field, stored[field.key]);
      controls[field.key] = new FormControl<FieldValue>(initial, {
        nonNullable: true,
        validators: buildValidators(field.rules, { legalAge, today }, field.key),
      });
    }
    const group: Step1Group = new FormGroup(controls);
    group.valueChanges
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(() => this.session.saveStep1(group.getRawValue()));
    return group;
  }

  protected control(key: string): FormControl<FieldValue> {
    return this.form()!.controls[key];
  }

  protected submit(): void {
    const form = this.form();
    if (!form) return;
    if (this.showErrors()) return;
    this.session.markStep1Completed();
    void this.router.navigate(['plans'], { relativeTo: this.route });
  }

  /** Marks everything touched; when invalid, announces and focuses the first bad field. */
  private showErrors(): boolean {
    const form = this.form();
    if (!form) return false;
    this.submitted.set(true);
    form.markAllAsTouched();
    if (form.invalid) {
      const count = Object.values(form.controls).filter((c) => c.invalid).length;
      // Same text twice in a row is not re-announced: clear first, then set on the next tick.
      this.statusMessage.set('');
      queueMicrotask(() =>
        this.statusMessage.set(
          count === 1 ? 'Revisa el campo marcado.' : `Revisa los ${count} campos marcados.`,
        ),
      );
      this.focusFirstInvalid(form);
      return true;
    }
    return false;
  }

  private focusFirstInvalid(form: Step1Group): void {
    for (const section of this.sections()) {
      for (const { field } of section.fields) {
        if (form.controls[field.key].invalid) {
          this.host.nativeElement.querySelector<HTMLElement>(`#${fieldInputId(field.key)}`)?.focus();
          return;
        }
      }
    }
  }
}

