:host {
  /* The card itself is the grid / slide item. */
  display: contents;
}

.plan-card {
  --plan-ring: var(--color-border);
  position: relative;
  display: grid;
  grid-template-rows: auto auto auto 1fr;
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  padding: var(--space-6) var(--space-4);
  border: 1px solid var(--plan-ring);
  border-radius: 14px;
  background: var(--color-surface);
  cursor: pointer;

  /* From 992px the cards share the page grid, so the rows align across cards. */
  @media (min-width: 992px) {
    grid-row: span 4;
    grid-template-rows: subgrid;
    padding: var(--space-6);
  }

  &:hover {
    --plan-ring: var(--color-action);
  }

  &--recommended {
    --plan-ring: var(--color-brand);
    /* 5px top border instead of 1px: 4px less padding keeps the rows aligned. */
    padding-top: calc(var(--space-6) - 4px);
    border-top: 5px solid var(--color-brand);
    box-shadow: inset 0 0 0 1px var(--color-brand);

    &:hover {
      --plan-ring: var(--color-brand);
    }
  }

